import{c as r,a7 as t,y as s,B as o,g as e,k as n,n as l,p as i,q as p,r as d}from"./chunks/framework.CbyRuOLv.js";const q=JSON.parse('{"title":"北海道旅3","description":"","frontmatter":{"title":"北海道旅3","date":"2026-04-27T00:00:00.000Z","outline":[2,3],"lastUpdated":true,"sidebar":false,"tags":["旅","北海道"]},"headers":[],"relativePath":"posts/hrd-travel_03.md","filePath":"posts/hrd-travel_03.md","lastUpdated":1785246058000}'),h={name:"posts/hrd-travel_03.md"};function g(_,a,c,m,b,u){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="🎥-北海道一周の旅-day-3" tabindex="-1">🎥 北海道一周の旅｜Day 3 <a class="header-anchor" href="#🎥-北海道一周の旅-day-3" aria-label="Permalink to “🎥 北海道一周の旅｜Day 3”">​</a></h1><h2 id="_4月28日-小樽-〜-千歳" tabindex="-1">4月28日 小樽 〜 千歳 <a class="header-anchor" href="#_4月28日-小樽-〜-千歳" aria-label="Permalink to “4月28日 小樽 〜 千歳”">​</a></h2><h1 id="旅途记录-4-28-4-29-旅の記録-4-28-4-29" tabindex="-1">旅途记录 4.28～4.29 / 旅の記録 4.28～4.29 <a class="header-anchor" href="#旅途记录-4-28-4-29-旅の記録-4-28-4-29" aria-label="Permalink to “旅途记录 4.28～4.29 / 旅の記録 4.28～4.29”">​</a></h1><h2 id="抵达北海道-北海道に到着" tabindex="-1">抵达北海道 / 北海道に到着 <a class="header-anchor" href="#抵达北海道-北海道に到着" aria-label="Permalink to “抵达北海道 / 北海道に到着”">​</a></h2><p>29号凌晨4点半，船到了。地点是小樽。 下船之后第一件事就是去了<strong>セイコーマート</strong>——北海道才有的便利店。 天还完全没亮，早得有点离谱。</p><p>29日の朝4時半、船が小樽に着いた。 下船してすぐ向かったのは<strong>セイコーマート</strong>。北海道ならではのコンビニだ。 外はまだ真っ暗で、とんでもない時間だった。</p><p><img src="'+e+'" alt="&quot;小樽&quot;" loading="lazy"></p><h2 id="沿海公路-海沿いの道" tabindex="-1">沿海公路 / 海沿いの道 <a class="header-anchor" href="#沿海公路-海沿いの道" aria-label="Permalink to “沿海公路 / 海沿いの道”">​</a></h2><p>从5号线拐上229号线，一路往前开。 北海道的路真的很宽，直线多，红绿灯又少，开起来特别爽。 风景也好，就这样舒舒服服地开了大约1个半小时，到了<strong>積丹半島</strong>。</p><p>5号線から229号線に入って、ひたすら走った。 北海道の道路って本当に広くて、直線が多くて、信号も少ない。運転してて気持ちよかった。 景色もよくて、気づいたら1時間半くらいで<strong>積丹半島</strong>に着いてた。</p><p><img src="'+n+'" alt="&quot;積丹半島&quot;" loading="lazy"></p><h2 id="積丹半島-積丹半島" tabindex="-1">積丹半島 / 積丹半島 <a class="header-anchor" href="#積丹半島-積丹半島" aria-label="Permalink to “積丹半島 / 積丹半島”">​</a></h2><p>北海道挺有名的观光地。但去得太早了，<strong>神威岬</strong>的门还锁着。 没办法就把车停在海边，在那里待了大约1个半小时。 钓鱼的人挺多的。海水透明度很高，从岬角那边看出去的海岸线也很漂亮。</p><p>北海道でも有名な観光地だ。でも早く着きすぎて、<strong>神威岬</strong>へのゲートがまだ閉まってた。 しょうがないので海岸に車を停めて、1時間半くらいぼーっとしてた。 釣りしてる人がたくさんいて、海の透明度がすごくて、岬から見える景色もきれいだった。</p><p><img src="'+l+'" alt="&quot;神威岬&quot;" loading="lazy"></p><h2 id="道の駅-→-羊蹄山-道の駅-→-羊蹄山" tabindex="-1">道の駅 → 羊蹄山 / 道の駅 → 羊蹄山 <a class="header-anchor" href="#道の駅-→-羊蹄山-道の駅-→-羊蹄山" aria-label="Permalink to “道の駅 → 羊蹄山 / 道の駅 → 羊蹄山”">​</a></h2><p>まだ時間があったので、そのまま<strong>羊蹄山</strong>方面へ。 途中の道の駅で揚げじゃがと揚げ芋を買って食べた。これが結構うまかった。 どこの道の駅だったか正確には覚えてないけど、地図見たらわかると思う。</p><p>时间还够，就继续往<strong>羊蹄山</strong>方向走。 途中在道の駅买了炸土豆和炸芋头，味道很不错。 具体哪个道の駅记不清了，不过地图上应该能查到。</p><p><img src="'+i+'" alt="&quot;羊蹄山&quot;" loading="lazy"></p><h2 id="洞爺湖-→-室蘭-→-千歳-→-札幌" tabindex="-1">洞爺湖 → 室蘭 → 千歳 → 札幌 <a class="header-anchor" href="#洞爺湖-→-室蘭-→-千歳-→-札幌" aria-label="Permalink to “洞爺湖 → 室蘭 → 千歳 → 札幌”">​</a></h2><p>そのあとは<strong>洞爺湖</strong>を通って<strong>室蘭</strong>へ、そこから<strong>千歳</strong>へ移動した。 夜は<strong>札幌</strong>まで行って、昔の知り合いと飯を食った。</p><p>之后经过<strong>洞爺湖</strong>到<strong>室蘭</strong>，再从室蘭去了<strong>千歳</strong>。 晚上又跑了趟<strong>札幌</strong>，和以前认识的人一起吃了饭。</p><p><img src="'+p+'" alt="&quot;白鳥大橋&quot;" loading="lazy"><img src="'+d+'" alt="&quot;味噌ラーメン&quot;" loading="lazy"></p><h2 id="返回千歳-千歳に戻る" tabindex="-1">返回千歳 / 千歳に戻る <a class="header-anchor" href="#返回千歳-千歳に戻る" aria-label="Permalink to “返回千歳 / 千歳に戻る”">​</a></h2><p>千歳の宿に戻ったのは夜の11時ごろ。 いっぱい走った一日だった。</p><p>回到千歳住的地方，已经是晚上11点了。 这一天，开了好长的路。</p>',26)])])}const P=r(h,[["render",g]]);export{q as __pageData,P as default};
